START TRANSACTION;CREATE TABLE pendant_sales(operation_id BIGINT UNSIGNED NOT NULL,player_id BIGINT UNSIGNED NOT NULL,inventory_instance_id BIGINT UNSIGNED NOT NULL,source_index INT UNSIGNED NOT NULL,point_price DECIMAL(30,0) NOT NULL,instance_version_before BIGINT UNSIGNED NOT NULL,instance_version_after BIGINT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),PRIMARY KEY(operation_id),UNIQUE KEY uq_pendant_sale_instance(inventory_instance_id),CONSTRAINT fk_pendant_sale_operation FOREIGN KEY(operation_id) REFERENCES operations(id),CONSTRAINT fk_pendant_sale_player FOREIGN KEY(player_id) REFERENCES players(id),CONSTRAINT fk_pendant_sale_instance FOREIGN KEY(inventory_instance_id) REFERENCES inventory_instances(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;INSERT INTO command_registry(command_code,handler_key,auth_scope,rollout_state,enabled,version) VALUES('PENDANT_SELL','pendant_sell','VERIFIED_USER','SHADOW',1,1) ON DUPLICATE KEY UPDATE handler_key=VALUES(handler_key),auth_scope=VALUES(auth_scope),version=VALUES(version);INSERT INTO command_aliases(command_text,command_code,active) VALUES('/펜던트판매','PENDANT_SELL',1) ON DUPLICATE KEY UPDATE command_code=VALUES(command_code),active=1;COMMIT;
